package com.horabase.api.request;
import com.horabase.api.auth.CurrentUser;import com.horabase.api.request.dto.*;import jakarta.validation.Valid;import org.springframework.http.HttpStatus;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController public class EmployeeRequestController{private final EmployeeRequestService service;public EmployeeRequestController(EmployeeRequestService s){service=s;}@PostMapping("/api/me/requests")@ResponseStatus(HttpStatus.CREATED)public EmployeeRequestResponse create(@AuthenticationPrincipal Jwt jwt,@Valid@RequestBody CreateEmployeeRequest q){return service.create(CurrentUser.from(jwt),q);}@GetMapping("/api/me/requests")public List<EmployeeRequestResponse>mine(@AuthenticationPrincipal Jwt jwt){return service.mine(CurrentUser.from(jwt));}@PostMapping("/api/me/requests/{id}/cancel")public EmployeeRequestResponse cancel(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id){return service.cancel(CurrentUser.from(jwt),id);}@GetMapping("/api/businesses/{businessId}/requests")@PreAuthorize("@businessSecurity.canAccess(authentication, #businessId)")public List<EmployeeRequestResponse>list(@PathVariable Long businessId,@RequestParam(required=false)EmployeeRequestStatus status){return service.list(businessId,status);}@PostMapping("/api/businesses/{businessId}/requests/{id}/approve")@PreAuthorize("@businessSecurity.canAccess(authentication, #businessId)")public EmployeeRequestResponse approve(@PathVariable Long businessId,@PathVariable Long id,@Valid@RequestBody ResolveEmployeeRequest q){return service.resolve(businessId,id,EmployeeRequestStatus.APPROVED,q);}@PostMapping("/api/businesses/{businessId}/requests/{id}/reject")@PreAuthorize("@businessSecurity.canAccess(authentication, #businessId)")public EmployeeRequestResponse reject(@PathVariable Long businessId,@PathVariable Long id,@Valid@RequestBody ResolveEmployeeRequest q){return service.resolve(businessId,id,EmployeeRequestStatus.REJECTED,q);}}
